package com.hireflow.api.notification; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity public class Notification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String email; String message; boolean readFlag=false; LocalDateTime createdAt=LocalDateTime.now(); public Notification(){} public Long getId(){return id;} public String getMessage(){return message;} public boolean isReadFlag(){return readFlag;} public LocalDateTime getCreatedAt(){return createdAt;} public void setEmail(String v){email=v;} public void setMessage(String v){message=v;} public void setReadFlag(boolean v){readFlag=v;} }